code_sketch:
sealed interface Op permits Get, Put, Log {}
record Get(String key) implements Op {}
record Put(String key, int value) implements Op {}
record Log(String message) implements Op {}

static int run(Op op, Store store) {
    return switch (op) {
        case Get g  -> store.read(g.key());
        case Put p  -> store.write(p.key(), p.value());
        case Log l  -> { store.log(l.message()); yield 0; }
    };  // no default: exhaustiveness is proven
}

