abstract class Op { abstract <R> R accept(Visitor<R> v); }
final class Get extends Op {
    final String key;
    <R> R accept(Visitor<R> v) { return v.visit(this); }
}
interface Visitor<R> { R visit(Get g); R visit(Put p); }
